INSERT INTO tb_course_reviews (
    id, user_id, course_id, rating, content, created_at, updated_at
) VALUES (
    #{id}, #{userId}, #{courseId}, #{rating},
    #{content, jdbcType=VARCHAR},
    #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM tb_course_reviews
    WHERE user_id = #{userId}
      AND course_id = #{courseId}
)

SELECT EXISTS (
    SELECT 1
    FROM tb_completions cp
    JOIN tb_enrollments e ON e.id = cp.enrollment_id
    WHERE e.user_id = #{userId}
      AND e.course_id = #{courseId}
      AND cp.status = 'COMPLETED'
      AND cp.confirmed_at IS NOT NULL
)

SELECT r.id, r.user_id, r.course_id, r.rating, r.content, r.created_at, c.title AS course_title, u.name AS user_name,
FROM tb_course_reviews r JOIN tb_courses c ON c.id = r.course_id JOIN tb_users u ON u.id = r.user_id
WHERE r.user_id = #{userId}
ORDER BY r.created_at DESC, r.id ASC LIMIT #{limit} OFFSET #{offset}

SELECT r.id, r.user_id, r.course_id, r.rating, r.content, r.created_at, c.title AS course_title, u.name AS user_name,
FROM tb_course_reviews r JOIN tb_courses c ON c.id = r.course_id JOIN tb_users u ON u.id = r.user_id
WHERE r.course_id = #{courseId} ORDER BY r.created_at DESC, r.id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM tb_course_reviews
WHERE course_id = #{courseId}
